//! The agent extraction path under test.
//!
//! Basic resources come from a PDF, then a model pass fills the
//! paper-artifacts schema and checks its own work. See
//! `docs/tasks/HANDOFF-extraction-spike.md`. The schemas are generated by
//! `scripts/spike/build_schemas.py`.

pub mod admission;
pub mod core_fields;
pub mod corrections;
pub mod features;
pub mod objects;
pub mod resources;
pub mod run;

/// The whole-paper artifacts a model fills in one pass, with every feature on.
pub const PAPER_ARTIFACTS_SCHEMA: &str = include_str!("../prompts/paper-artifacts.schema.json");

/// The fields every extraction needs, without any optional feature.
pub const CORE_SCHEMA: &str = include_str!("../prompts/paper-core.schema.json");

/// The objects printed on a few pages of one chunk.
pub const OBJECTS_SCHEMA: &str = include_str!("../prompts/paper-objects.schema.json");

/// The argument as ordered segments.
pub const SUPERCUT_SCHEMA: &str = include_str!("../prompts/paper-supercut.schema.json");

/// Claims, method, numbers, limitations, open questions and the read signal.
pub const ANALYSIS_SCHEMA: &str = include_str!("../prompts/paper-analysis.schema.json");

/// Notation and glossary terms.
pub const GLOSSARY_SCHEMA: &str = include_str!("../prompts/paper-glossary.schema.json");

/// One schema per core field, for the fan-out mode.
pub const IDENTITY_SCHEMA: &str = include_str!("../prompts/paper-field-identity.schema.json");
pub const TYPE_SCHEMA: &str = include_str!("../prompts/paper-field-type.schema.json");
pub const ABSTRACT_SCHEMA: &str = include_str!("../prompts/paper-field-abstract.schema.json");
pub const CARD_SCHEMA: &str = include_str!("../prompts/paper-field-card.schema.json");
pub const QUESTION_SCHEMA: &str = include_str!("../prompts/paper-field-question.schema.json");
pub const SECTIONS_SCHEMA: &str = include_str!("../prompts/paper-field-sections.schema.json");
pub const REFERENCES_SCHEMA: &str = include_str!("../prompts/paper-field-references.schema.json");
pub const CITATIONS_SCHEMA: &str = include_str!("../prompts/paper-field-citations.schema.json");
pub const RELATIONS_SCHEMA: &str = include_str!("../prompts/paper-field-relations.schema.json");

/// Pass 2: corrections and flags against a pass-1 draft.
pub const CHECK_SCHEMA: &str = include_str!("../prompts/paper-artifacts-check.schema.json");

/// Bounded reconciliation of quotes that are not verbatim in the source.
pub const REPAIR_SCHEMA: &str = include_str!("../prompts/paper-artifacts-repair.schema.json");

#[cfg(test)]
mod tests {
    use serde_json::Value;

    use super::*;

    /// Every rule `OpenRouter` strict mode enforces that a hand edit could break.
    fn strict_violations(schema: &Value, path: &str, found: &mut Vec<String>) {
        let Some(object) = schema.as_object() else {
            found.push(format!("{path}: schema is not an object"));
            return;
        };
        if let Some(Value::Object(properties)) = object.get("properties") {
            if object.get("additionalProperties") != Some(&Value::Bool(false)) {
                found.push(format!("{path}: additionalProperties must be false"));
            }
            let required = object
                .get("required")
                .and_then(Value::as_array)
                .map(|keys| keys.iter().filter_map(Value::as_str).collect::<Vec<_>>())
                .unwrap_or_default();
            for (key, child) in properties {
                if !required.contains(&key.as_str()) {
                    found.push(format!("{path}/{key}: not listed in required"));
                }
                strict_violations(child, &format!("{path}/{key}"), found);
            }
        }
        if let Some(items) = object.get("items") {
            strict_violations(items, &format!("{path}[]"), found);
        }
        for keyword in ["$ref", "oneOf", "allOf", "patternProperties"] {
            if object.contains_key(keyword) {
                found.push(format!(
                    "{path}: {keyword} is not used in strict schemas here"
                ));
            }
        }
    }

    #[test]
    fn should_satisfy_strict_mode_when_any_schema_is_edited() {
        for (name, text) in [
            ("paper-artifacts", PAPER_ARTIFACTS_SCHEMA),
            ("core", CORE_SCHEMA),
            ("objects", OBJECTS_SCHEMA),
            ("supercut", SUPERCUT_SCHEMA),
            ("analysis", ANALYSIS_SCHEMA),
            ("glossary", GLOSSARY_SCHEMA),
            ("field-identity", IDENTITY_SCHEMA),
            ("field-type", TYPE_SCHEMA),
            ("field-abstract", ABSTRACT_SCHEMA),
            ("field-card", CARD_SCHEMA),
            ("field-question", QUESTION_SCHEMA),
            ("field-sections", SECTIONS_SCHEMA),
            ("field-references", REFERENCES_SCHEMA),
            ("field-citations", CITATIONS_SCHEMA),
            ("field-relations", RELATIONS_SCHEMA),
            ("check", CHECK_SCHEMA),
            ("repair", REPAIR_SCHEMA),
        ] {
            let schema: Value = serde_json::from_str(text).expect("schema is JSON");
            let mut found = Vec::new();
            strict_violations(&schema, name, &mut found);
            assert!(found.is_empty(), "{found:#?}");
        }
    }

    #[test]
    fn should_cover_every_tier_one_field_when_the_schema_is_loaded() {
        let schema: Value = serde_json::from_str(PAPER_ARTIFACTS_SCHEMA).expect("schema");
        let required = schema["required"].as_array().expect("required");
        for field in [
            "identity",
            "type",
            "abstract",
            "card",
            "supercut",
            "question",
            "claims",
            "method",
            "key_numbers",
            "limitations",
            "open_questions",
            "objects",
            "notation",
            "glossary",
            "references",
            "citations",
            "relations",
        ] {
            assert!(required.contains(&Value::from(field)), "missing {field}");
        }
    }

    #[test]
    fn should_use_the_citation_graph_vocabulary_when_labelling_relations() {
        let schema: Value = serde_json::from_str(PAPER_ARTIFACTS_SCHEMA).expect("schema");
        let kinds = &schema["properties"]["relations"]["items"]["properties"]["relation"]["enum"];
        assert_eq!(
            kinds,
            &serde_json::json!(lysilogy_ingest::labels::RELATIONS)
        );
    }
}
